{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "@id": "https://myugcvideo.in/services#faq",
    "mainEntity": [
        {
            "@type": "Question",
            "name": "What commercial usage rights do you provide?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "All delivered UGC video assets include 100% full commercial digital advertising rights. Your brand can deploy assets across Meta (Facebook & Instagram), TikTok, YouTube, Pinterest, Google, and website landing pages without recurring talent royalties or expiration dates."
            }
        },
        {
            "@type": "Question",
            "name": "How long does production take?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Estimated production time is 7 to 12 business days from creative brief approval and product sample arrival at our creator or studio location. Timelines depend on project scope, creator availability, feedback and approvals."
            }
        },
        {
            "@type": "Question",
            "name": "How do you select creators?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "We evaluate creators based on demographic alignment, on-camera presence, natural domestic lighting environment, and audio clarity. Creators are cast specifically for your product niche and target customer profile rather than generic rosters."
            }
        },
        {
            "@type": "Question",
            "name": "Do clients approve scripts before filming?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Yes. We submit structured storyboards, opening 3-second hook variations, key benefit talking points, and calls-to-action for your written sign-off before sending product samples to creators or initiating studio filming."
            }
        },
        {
            "@type": "Question",
            "name": "What aspect ratios are delivered?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Our primary standard is native 9:16 vertical (1080\u00d71920) optimized for Reels, TikTok, and Shorts. We also export 4:5 portrait (1080\u00d71350), 1:1 square (1080\u00d71080), and 16:9 landscape (1920\u00d71080) upon request, delivered as high-bitrate MP4 files with burned-in captions and SRT files."
            }
        },
        {
            "@type": "Question",
            "name": "How are revisions handled?",
            "acceptedAnswer": {
                "@type": "Answer",
                "text": "Every project includes post-production revisions covering editorial pacing, text callouts, audio balance, and subtitle styling. If content deviates from the agreed creative brief, adjustments and reshoots are completed promptly."
            }
        }
    ]
}

